import {detectWarnings,detectionTimeline,detectionTaskContext,dateOffset,SIGNAL_RULES} from './detection-core.mjs';
import {detectionExercise,REPLAY_DAYS,evaluateDetectionExercise} from './detection-fixtures.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const selected=(list,value)=>list.map(s=>`<option${s===value?' selected':''}>${esc(s)}</option>`).join('');
export function detectionDesk({getWorkspace,today,canChange,feedback}){
  let mode='workspace',settings={knownBy:today(),lookbackDays:7,scope:'All'},step=0,timer=null,showOutcomes=false;
  const exercise=detectionExercise();
  const stop=()=>{if(timer)clearInterval(timer);timer=null;};
  const input=()=>mode==='exercise'?exercise:getWorkspace();
  const window=()=>mode==='exercise'?{knownBy:REPLAY_DAYS[step],lookbackDays:7,scope:'All'}:settings;
  function timelineHTML(report){
    const from=mode==='exercise'?REPLAY_DAYS[0]:dateOffset(report.window.knownBy,-6);
    const rows=detectionTimeline(input(),{from,to:report.window.knownBy,scope:report.window.scope,lookbackDays:report.window.lookbackDays});
    const symbols={'Watch':'W','Warning candidate':'!','Contested warning candidate':'!?','No rule warning':'·','No report coverage':'—'};
    return `<section class="detect-timeline"><h3>Warnings over time</h3><p>Recomputed from reports available on each date; future reports and corrections stay excluded. W = watch, ! = warning candidate, !? = contested, · = no rule warning, — = no report coverage.</p><div class="detect-scroll"><table><caption>Case state by known-by day</caption><thead><tr><th scope="col">Existing case</th>${rows.map(r=>`<th scope="col">${r.knownBy.slice(5)}</th>`).join('')}</tr></thead><tbody>${report.cases.map(c=>`<tr><th scope="row">${esc(c.title)}</th>${rows.map(r=>{const s=r.cases.find(x=>x.assessmentId===c.assessmentId);return `<td class="detect-cell" data-warning="${!!s?.warning}" title="${esc(s?.state??'No report coverage')}">${symbols[s?.state]??'—'}<span class="sr-only"> ${esc(s?.state)}</span></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></section>`;
  }
  function recordHTML(r){
    return `<article class="detect-source"><h4>${esc(r.title)}</h4><p class="small-label">${esc(r.recordKey)} / ${r.synthetic?'SYNTHETIC':'ENTERED SOURCE / UNVERIFIED'}</p><p>${esc(r.publisher)} · Group ${esc(r.originGroup)}<br>Published ${r.reportedAt} · Recorded ${r.recordedAt}</p>${r.outsidePublicationWindow?'<p class="notice">Publication predates this rolling window; retained as context and excluded from current warning escalation.</p>':''}${r.duplicateOf?`<p class="notice">Identical normalized text to ${esc(r.duplicateOf)}; excluded from positive-group escalation.</p>`:''}<blockquote class="source-excerpt">${esc(r.text)}</blockquote>${r.signals.map(s=>`<div class="detect-hit"><span class="tag">${esc(s.label)}</span> <span class="tag">${esc(s.polarity)}</span><p>Exact hit “${esc(s.quote)}” · UTF-16 [${s.start}, ${s.end})</p><blockquote>${esc(s.clause.quote)}</blockquote></div>`).join('')||'<p class="muted">No supported lexical security signal in this report.</p>'}${r.truncated?'<p class="error">Signal extraction capped at 80 hits; the full original remains above.</p>':''}<p class="muted">Date parser: ${esc(r.dateMentions.dateState)}. ${r.dateMentions.dates.map(d=>`“${esc(d.quote)}”`).join('; ')||'No supported explicit date mention.'} These are mentions, not a predicted event time.</p>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open source reference</a>`:''}</article>`;
  }
  function outcomesHTML(){
    if(!showOutcomes)return '';
    const result=evaluateDetectionExercise();
    return `<section class="detect-outcomes"><h3>Authored outcome check</h3><p class="notice">${result.timely} timely warning · ${result.falseWarnings} false warning · ${result.missed} missed incident · ${result.uneventful} uneventful control. ${esc(result.limitation)}</p>${result.results.map(r=>`<article class="detect-outcome"><h4>${esc(exercise.assessments.find(c=>c.id===r.assessmentId).title)} / ${esc(r.result)}</h4><p>First pre-outcome warning: ${r.firstWarning??'None'} · ${r.leadDays===null?'No incident lead-time result':`${r.leadDays} days before the authored incident`}.</p><p>${esc(r.description)} Outcomes become known ${r.knownAt}; they are never detector inputs.</p></article>`).join('')}<p>Authored precision ${(result.precision*100).toFixed(0)}% / recall ${(result.recall*100).toFixed(0)}%. No calibrated probability or prevention result is claimed. The missed incident and false warning are retained.</p></section>`;
  }
  function results(){
    const r=detectWarnings(input(),window());
    $('detect-results').innerHTML=`<div class="detect-metrics" aria-label="Detection results">${[['Reports scanned',r.recordsScanned],['Signal hits',r.signalCount],['Warning candidates',r.warningCount],['Watch cases',r.watchCount],['Coverage gaps',r.coverageGapCount]].map(([label,n])=>`<div><span>${label}</span><strong>${n}</strong></div>`).join('')}</div>${timelineHTML(r)}<h3>Evidence-linked warning queue</h3><p>Grouped by existing case, in case order. Source labels do not establish independence; reports in one case may describe different events. These are verification candidates, without attack probabilities.</p>${r.cases.map(c=>`<article class="detect-case" data-warning="${c.warning}"><div class="case-heading"><div><p class="small-label">${esc(c.scope)} / ${esc(c.area)}</p><h3>${esc(c.title)}</h3></div><span class="chip">${esc(c.state)}</span></div><p>${esc(c.reason)}</p><div class="detect-flow" aria-label="Warning evidence chain"><span>${c.positiveCount} active original reports</span><span>→ ${c.positiveGroups.length} recorded groups</span><span>→ ${c.activeCodes.map(code=>SIGNAL_RULES.find(r=>r.code===code).label).join(' + ')||'No active category'}</span><span>→ ${esc(c.state)}</span></div><p>${c.denialCount} denial/withdrawal report(s) · ${c.contextCount} context-only report(s) · ${c.duplicateCount} identical-text duplicate(s).</p>${mode==='workspace'&&['Watch','Warning candidate','Contested warning candidate'].includes(c.state)?`<button data-detection-followup="${esc(c.assessmentId)}">Prepare warning verification task</button>`:''}${mode==='workspace'?`<button data-task-case="${esc(c.assessmentId)}">Open assessment</button>`:'<p class="muted">Isolated fictional replay. Reports are not added to your workspace and no task or operational action is sent.</p>'}<details><summary>Inspect ${c.records.length} source report(s) and extracted clauses</summary>${c.records.map(recordHTML).join('')||'<p>No current source reports for this case.</p>'}</details></article>`).join('')||'<p>No cases in the selected geographic scope.</p>'}${outcomesHTML()}`;
    if(mode==='exercise'){$('detect-replay-day').textContent=`Day ${step+1} / ${REPLAY_DAYS.length} · Known by ${REPLAY_DAYS[step]}`;$('detect-step').value=String(step);$('detect-prev').disabled=step===0;$('detect-next').disabled=step===REPLAY_DAYS.length-1;$('detect-reveal').disabled=step!==REPLAY_DAYS.length-1;$('detect-play').textContent=timer?'Pause report arrival':'Play report arrival';}
  }
  function render(){
    $('content').innerHTML=`<section class="panel detection-console"><div class="panel-heading"><div><h2>Detection console</h2><span class="muted">Ingest → extract → connect → warn → verify</span></div><span class="chip">${mode==='exercise'?'SYNTHETIC REPLAY':'WORKSPACE REPORTS'}</span></div><div class="case-body"><p>Automatic security-signal extraction and time-based warning candidates from retained original reports. English/Hindi lexical rules preserve exact clauses, denials, general guidance and source dependence.</p><div class="actions"><button id="detect-workspace"${mode==='workspace'?' disabled':''}>Analyze workspace reports</button><button id="detect-exercise" class="primary">Open synthetic incident replay</button><button data-open-view="collection">Ingest permitted source capture</button><button data-open-view="intake">Stage source report</button></div>${mode==='workspace'?`<form id="detect-form"><div class="signal-fields"><div><label for="detect-date">Known by</label><input id="detect-date" type="date" value="${settings.knownBy}" required></div><div><label for="detect-window">Rolling arrival window</label><select id="detect-window">${[3,7,14,30].map(n=>`<option value="${n}"${n===settings.lookbackDays?' selected':''}>${n} days</option>`).join('')}</select></div><div><label for="detect-scope">Geographic scope</label><select id="detect-scope">${selected(['All','Domestic','Cross-border','International'],settings.scope)}</select></div></div><p id="detect-error" class="error" role="alert"></p><button type="submit">Run detection</button></form>`:`<section class="detect-replay"><h3>Report-arrival replay</h3><p>Four fictional cases: an early aerial warning, a suspicious-object false alarm, a missed incident, and routine/advisory controls. No real person, facility, attack path or event is represented.</p><p id="detect-replay-day" aria-live="polite"></p><label for="detect-step">Report arrival day</label><input id="detect-step" type="range" min="0" max="${REPLAY_DAYS.length-1}" value="${step}"><div class="actions"><button id="detect-prev">Previous day</button><button id="detect-play">Play report arrival</button><button id="detect-next">Next day</button><button id="detect-first-warning">Jump to first warning</button><button id="detect-reveal">Reveal authored outcomes</button></div><p>Later outcomes stay outside the detection pipeline; reveal them after reaching the final day.</p></section>`}<div id="detect-results"></div><details class="detect-method"><summary>Detection rule and current limits</summary><p>Warning candidate: at least two distinct recorded source-group labels have active reports, containing an explicit threat phrase or at least two security-signal categories. A matching-category denial keeps the candidate contested. One positive group stays Watch. Identical normalized text is counted once per case. Other reposts need correct source-group metadata.</p><p>Active reports contain a supported phrase with an attributed report or uncertainty cue. General guidance, conditional/training wording and limited negations stay visible without positive escalation. These lexical rules can misinterpret negation, satire, translation, an unrelated date or ambiguous clauses and miss unfamiliar wording. Full source text remains available. Detection runs on opening or applying this view; no background worker, live social/CCTV feed, individual intent classifier or automated response exists.</p><p>Newly recorded original reports in the selected arrival window are scanned. Both publication and recorded dates must be no later than Known by. Older publications stay visible as context and cannot escalate a current warning. Source-derived analyst statements are not counted again. Warning changes are recomputed from current workspace snapshots, not a protected historical alert ledger. Sources, identities, labels and authenticity remain unverified. No warning does not establish safety.</p></details></div></section>`;
    results();
  }
  document.addEventListener('submit',event=>{if(event.target.id!=='detect-form')return;event.preventDefault();try{const next={knownBy:$('detect-date').value,lookbackDays:Number($('detect-window').value),scope:$('detect-scope').value};detectWarnings(getWorkspace(),next);settings=next;results();$('detect-error').textContent='';feedback('Detection completed on current retained reports. Inspect candidates and source clauses.');}catch(e){$('detect-error').textContent=e.message;}});
  document.addEventListener('input',event=>{if(event.target.id==='detect-step'){stop();step=Number(event.target.value);showOutcomes=false;results();}});
  document.addEventListener('click',event=>{
    const id=event.target.closest('button')?.id;if(!id?.startsWith('detect-')||!['detect-workspace','detect-exercise','detect-prev','detect-next','detect-play','detect-first-warning','detect-reveal'].includes(id))return;
    if(!canChange())return;
    if(id==='detect-play'){if(timer){stop();results();return;}if(step===REPLAY_DAYS.length-1){step=0;showOutcomes=false;}timer=setInterval(()=>{if(!$('detect-step')){stop();return;}step++;showOutcomes=false;if(step===REPLAY_DAYS.length-1)stop();results();},1800);results();return;}
    stop();
    if(id==='detect-workspace'){mode='workspace';render();return;}
    if(id==='detect-exercise'){mode='exercise';step=0;showOutcomes=false;render();feedback('Isolated authored replay opened. Your workspace is unchanged.');return;}
    if(id==='detect-reveal'){showOutcomes=true;results();return;}
    if(id==='detect-first-warning')step=2;else step=Math.max(0,Math.min(REPLAY_DAYS.length-1,step+(id==='detect-next'?1:-1)));
    showOutcomes=false;results();
  });
  return {render,stop,reset:()=>{stop();mode='workspace';showOutcomes=false;settings={knownBy:today(),lookbackDays:7,scope:'All'};},taskContext:id=>{if(mode!=='workspace')throw Error('Synthetic replay does not create workspace tasks.');return detectionTaskContext(getWorkspace(),settings,id);}};
}
